import{_ as t,a0 as p,w as r,s as o,ao as d,I as l,x as a,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"CentOS 7 上的 FirewallD 簡明指南 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS 7 上的 FirewallD 簡明指南 | LCTT (201703) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS 7 上的 FirewallD 簡明指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS 7 上的 FirewallD 簡明指南 | LCTT (201703) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201703/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7","title":"CentOS 7 上的 FirewallD 簡明指南","tag":"201703","desc":""},"relativePath":"201703/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md","filePath":"[post].md"}'),c={name:"201703/20170213 Set Up and Configure a Firewall with FirewallD on CentOS 7.md"};function h(g,s,m,f,u,b){const e=p("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="centos-7-上的-firewalld-簡明指南" tabindex="-1">CentOS 7 上的 FirewallD 簡明指南 <a class="header-anchor" href="#centos-7-上的-firewalld-簡明指南" aria-label="Permalink to “CentOS 7 上的 FirewallD 簡明指南”">​</a></h1><p><img src="https://www.rosehosting.com/blog/wp-content/uploads/2017/02/set-up-and-configure-a-firewall-with-firewalld-on-centos-7.jpg" alt=""></p><p>FirewallD 是 CentOS 7 服務器上默認可用的防火牆管理工具。基本上，它是 iptables 的封裝，有圖形配置工具 firewall-config 和命令列工具 <code>firewall-cmd</code>。使用 iptables 服務，每次改動都要求刷新舊規則，並且從 <code>/etc/sysconfig/iptables</code> 讀取新規則，然而 firewalld 只應用改動了的不同部分。</p><h3 id="firewalld-的區域-zone" tabindex="-1">FirewallD 的區域（zone） <a class="header-anchor" href="#firewalld-的區域-zone" aria-label="Permalink to “FirewallD 的區域（zone）”">​</a></h3><p>FirewallD 使用服務（service） 和區域（zone）來代替 iptables 的規則（rule）和鏈（chain）。</p><p>默認情況下，有以下的區域（zone）可用：</p><ul><li><strong>drop</strong> – 丟棄所有傳入的網絡數據包並且無回應，只有傳出網絡連接可用。</li><li><strong>block</strong> — 拒絕所有傳入網絡數據包並回應一條主機禁止的 ICMP 消息，只有傳出網絡連接可用。</li><li><strong>public</strong> — 只接受被選擇的傳入網絡連接，用於公共區域。</li><li><strong>external</strong> — 用於啓用了地址偽裝的外部網絡，只接受選定的傳入網絡連接。</li><li><strong>dmz</strong> — DMZ 隔離區，外部受限地訪問內部網絡，只接受選定的傳入網絡連接。</li><li><strong>work</strong> — 對於處在你工作區域內的計算機，只接受被選擇的傳入網絡連接。</li><li><strong>home</strong> — 對於處在你家庭區域內的計算機，只接受被選擇的傳入網絡連接。</li><li><strong>internal</strong> — 對於處在你內部網絡的計算機，只接受被選擇的傳入網絡連接。</li><li><strong>trusted</strong> — 所有網絡連接都接受。</li></ul><p>要列出所有可用的區域，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-zones</span></span>
<span class="line"><span>work drop internal external trusted home dmz public block</span></span></code></pre></div><p>列出默認的區域 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>public</span></span></code></pre></div><p>改變默認的區域 ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><h3 id="firewalld-服務" tabindex="-1">FirewallD 服務 <a class="header-anchor" href="#firewalld-服務" aria-label="Permalink to “FirewallD 服務”">​</a></h3><p>FirewallD 服務使用 XML 配置文件，記錄了 firewalld 服務信息。</p><p>列出所有可用的服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --get-services</span></span>
<span class="line"><span>amanda-client amanda-k5-client bacula bacula-client ceph ceph-mon dhcp dhcpv6 dhcpv6-client dns docker-registry dropbox-lansync freeipa-ldap freeipa-ldaps freeipa-replication ftp high-availability http https imap imaps ipp ipp-client ipsec iscsi-target kadmin kerberos kpasswd ldap ldaps libvirt libvirt-tls mdns mosh mountd ms-wbt mysql nfs ntp openvpn pmcd pmproxy pmwebapi pmwebapis pop3 pop3s postgresql privoxy proxy-dhcp ptp pulseaudio puppetmaster radius rpc-bind rsyncd samba samba-client sane smtp smtps snmp snmptrap squid ssh synergy syslog syslog-tls telnet tftp tftp-client tinc tor-socks transmission-client vdsm vnc-server wbem-https xmpp-bosh xmpp-client xmpp-local xmpp-server</span></span></code></pre></div><p>XML 配置文件存儲在 <code>/usr/lib/firewalld/services/</code> 和 <code>/etc/firewalld/services/</code> 目錄下。</p><h3 id="用-firewalld-配置你的防火牆" tabindex="-1">用 FirewallD 配置你的防火牆 <a class="header-anchor" href="#用-firewalld-配置你的防火牆" aria-label="Permalink to “用 FirewallD 配置你的防火牆”">​</a></h3><p>作為一個例子，假設你正在運行一個 web 服務器，SSH 服務端口為 7022 ，以及郵件服務，你可以利用 FirewallD 這樣配置你的服務器:</p><p>首先設置默認區為 dmz。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --set-default-zone=dmz</span></span>
<span class="line"><span># firewall-cmd --get-default-zone</span></span>
<span class="line"><span>dmz</span></span></code></pre></div><p>為 dmz 區添加持久性的 HTTP 和 HTTPS 規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd --zone=dmz --add-service=http --permanent</span></span>
<span class="line"><span># firewall-cmd --zone=dmz --add-service=https --permanent</span></span></code></pre></div><p>開啓端口 25 (SMTP) 和端口 465 (SMTPS) ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=smtp --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=smtps --permanent</span></span></code></pre></div><p>開啓 IMAP、IMAPS、POP3 和 POP3S 端口：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --zone=dmz --add-service=imap --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=imaps --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3 --permanent</span></span>
<span class="line"><span>firewall-cmd --zone=dmz --add-service=pop3s --permanent</span></span></code></pre></div><p>因為將 SSH 端口改到了 7022，所以要移除 ssh 服務（端口 22），開啓端口 7022：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --remove-service=ssh --permanent</span></span>
<span class="line"><span>firewall-cmd --add-port=7022/tcp --permanent</span></span></code></pre></div><p>要應用這些更改，我們需要重新加載防火牆：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>firewall-cmd --reload</span></span></code></pre></div><p>最後可以列出這些規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># firewall-cmd –list-all</span></span>
<span class="line"><span>dmz</span></span>
<span class="line"><span>target: default</span></span>
<span class="line"><span>icmp-block-inversion: no</span></span>
<span class="line"><span>interfaces:</span></span>
<span class="line"><span>sources:</span></span>
<span class="line"><span>services: http https imap imaps pop3 pop3s smtp smtps</span></span>
<span class="line"><span>ports: 7022/tcp</span></span>
<span class="line"><span>protocols:</span></span>
<span class="line"><span>masquerade: no</span></span>
<span class="line"><span>forward-ports:</span></span>
<span class="line"><span>sourceports:</span></span>
<span class="line"><span>icmp-blocks:</span></span>
<span class="line"><span>rich rules:</span></span></code></pre></div><hr><p>PS. 如果你喜歡這篇文章，請在下面留下一個回覆。謝謝。</p><hr>`,37)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/",-1)])]),_:1})]),s[16]||(s[16]=l("p",null,"譯者簡介：",-1)),l("p",null,[i(e,{href:"http://locez.com"},{default:n(()=>[...s[2]||(s[2]=[a("Locez",-1)])]),_:1}),s[3]||(s[3]=a(" 是一個喜歡技術，喜歡折騰的 Linuxer，靠着對 Linux 的興趣自學了很多 Linux 相關的知識，並且志在於為 Linux 在中國普及出一份力。",-1))]),l("p",null,[s[7]||(s[7]=a("作者：",-1)),i(e,{href:"https://www.rosehosting.com/blog/set-up-and-configure-a-firewall-with-firewalld-on-centos-7/"},{default:n(()=>[...s[4]||(s[4]=[a("rosehosting.com",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(e,{href:"https://github.com/locez"},{default:n(()=>[...s[5]||(s[5]=[a("Locez",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(e,{href:"https://github.com/jasminepeng"},{default:n(()=>[...s[6]||(s[6]=[a("jasminepeng",-1)])]),_:1})]),l("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const v=t(c,[["render",h]]);export{C as __pageData,v as default};
